INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/civilpro','CivilPro — Structural Analysis Desktop Prototype','portfolio','published','{"body": "The CivilPro repository contains the CivilStructure desktop prototype: a React/Three.js modelling interface connected to a Rust engineering backend through Tauri. Documented panels cover materials and sections, loading, foundations and result inspection.\n\nThe source includes structural-analysis, load-generation, GPU-compute and export work. This portfolio record describes a development prototype; independent calculation validation, certified design-code compliance and production engineering readiness are not asserted.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "Engineering Tools", "featured": false, "features": ["Interactive 3D model viewport", "Material, section and load-case panels", "Rust calculation and GPU-compute implementation", "Displacement, member-force and reaction result views", "DXF drawing and Excel report export commands"], "description": "A desktop engineering prototype combining interactive 3D structural modelling with Rust-based calculation and reporting workflows.", "technologies": ["Tauri", "Rust", "React", "TypeScript", "Three.js", "WGSL"], "project_status": "Development prototype · desktop engineering", "evidence_attested": true, "challenges": ["Connecting calculation workflows to an interactive 3D desktop interface."], "platforms": ["Desktop prototype"], "media_ids": []}'::jsonb,'{"body": "The CivilPro repository contains the CivilStructure desktop prototype: a React/Three.js modelling interface connected to a Rust engineering backend through Tauri. Documented panels cover materials and sections, loading, foundations and result inspection.\n\nThe source includes structural-analysis, load-generation, GPU-compute and export work. This portfolio record describes a development prototype; independent calculation validation, certified design-code compliance and production engineering readiness are not asserted.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "Engineering Tools", "featured": false, "features": ["Interactive 3D model viewport", "Material, section and load-case panels", "Rust calculation and GPU-compute implementation", "Displacement, member-force and reaction result views", "DXF drawing and Excel report export commands"], "description": "A desktop engineering prototype combining interactive 3D structural modelling with Rust-based calculation and reporting workflows.", "technologies": ["Tauri", "Rust", "React", "TypeScript", "Three.js", "WGSL"], "project_status": "Development prototype · desktop engineering", "evidence_attested": true, "challenges": ["Connecting calculation workflows to an interactive 3D desktop interface."], "platforms": ["Desktop prototype"], "media_ids": []}'::jsonb,'{"title": "CivilPro — Structural Analysis Desktop Prototype | Anil Bishnoi", "description": "A desktop engineering prototype combining interactive 3D structural modelling with Rust-based calculation and reporting workflows.", "canonical": "https://anibish.com/portfolio/civilpro"}'::jsonb,'{"title": "CivilPro — Structural Analysis Desktop Prototype | Anil Bishnoi", "description": "A desktop engineering prototype combining interactive 3D structural modelling with Rust-based calculation and reporting workflows.", "canonical": "https://anibish.com/portfolio/civilpro"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/estiva','Estiva — Property Marketplace','portfolio','published','{"body": "Estiva connects property discovery with listing information, agent-facing workflows and enquiry management. Its public website presents property and location discovery, agent profiles and listing opportunities across residential, land and commercial categories.\n\nThe historical HomesWhere repository name belongs to this same product record. The documented work includes a responsive web application, backend services and a mobile wrapper project; these are grouped as one product history.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://estiva.in/"}], "category": "Web & SaaS Applications", "featured": true, "features": ["Property search and detail-page experiences", "Location and agent discovery", "Listing and enquiry-management workflows", "Customer, agent and administrative workspaces", "Responsive web and mobile-wrapper project"], "description": "A real-estate marketplace with property discovery, listing details and role-specific customer, agent and administration workspaces.", "technologies": ["Next.js", "TypeScript", "Fastify", "PostgreSQL", "Capacitor"], "project_status": "Public website · property marketplace engineering", "evidence_attested": true, "challenges": [], "platforms": ["Web", "Mobile wrapper project"], "media_ids": []}'::jsonb,'{"body": "Estiva connects property discovery with listing information, agent-facing workflows and enquiry management. Its public website presents property and location discovery, agent profiles and listing opportunities across residential, land and commercial categories.\n\nThe historical HomesWhere repository name belongs to this same product record. The documented work includes a responsive web application, 