INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/gadgetswhere','GadgetsWhere — Product Catalogue & Comparison','portfolio','published','{"body": "GadgetsWhere presents gadget discovery, product comparisons, reviews, news and deals for the Indian market. The documented catalogue work covers mobile phones, tablets and laptops, with typed product information and a public/admin application shell.\n\nThe current public website is reachable. The inspected repository describes an ongoing platform conversion, so this entry distinguishes documented catalogue and application work from full web/mobile feature parity.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://gadgetswhere.com/"}], "category": "Web & SaaS Applications", "featured": true, "features": ["Mobile-phone, tablet and laptop catalogue work", "Product search and comparison experiences", "Public editorial and category sections", "Authentication and administrative application foundations", "Responsive web with a mobile-client codebase"], "description": "A gadget research and catalogue platform for Indian buyers, with product discovery, comparison and editorial experiences.", "technologies": ["Next.js", "TypeScript", "NestJS", "React Native", "PostgreSQL"], "project_status": "Public website · platform development in progress", "evidence_attested": true, "challenges": [], "platforms": ["Web", "Mobile codebase"], "media_ids": []}'::jsonb,'{"body": "GadgetsWhere presents gadget discovery, product comparisons, reviews, news and deals for the Indian market. The documented catalogue work covers mobile phones, tablets and laptops, with typed product information and a public/admin application shell.\n\nThe current public website is reachable. The inspected repository describes an ongoing platform conversion, so this entry distinguishes documented catalogue and application work from full web/mobile feature parity.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://gadgetswhere.com/"}], "category": "Web & SaaS Applications", "featured": true, "features": ["Mobile-phone, tablet and laptop catalogue work", "Product search and comparison experiences", "Public editorial and category sections", "Authentication and administrative application foundations", "Responsive web with a mobile-client codebase"], "description": "A gadget research and catalogue platform for Indian buyers, with product discovery, comparison and editorial experiences.", "technologies": ["Next.js", "TypeScript", "NestJS", "React Native", "PostgreSQL"], "project_status": "Public website · platform development in progress", "evidence_attested": true, "challenges": [], "platforms": ["Web", "Mobile codebase"], "media_ids": []}'::jsonb,'{"title": "GadgetsWhere — Product Catalogue & Comparison | Anil Bishnoi", "description": "A gadget research and catalogue platform for Indian buyers, with product discovery, comparison and editorial experiences.", "canonical": "https://anibish.com/portfolio/gadgetswhere"}'::jsonb,'{"title": "GadgetsWhere — Product Catalogue & Comparison | Anil Bishnoi", "description": "A gadget research and catalogue platform for Indian buyers, with product discovery, comparison and editorial experiences.", "canonical": "https://anibish.com/portfolio/gadgetswhere"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/local-ai-audio-tools','Local AI Audio Tools — Script & Content Factory','portfolio','published','{"body": "Script Factory and Content Factory turn written scripts into spoken audio using locally managed models and user-provided voice references. Their workflows cover project/script editing, voice profiles, segmented generation, selective regeneration, playback and final audio assembly.\n\nThese related applications are grouped as an engineering collection, rather than treated as a single renamed product. The documented stack combines Tauri, React, Rust and a local MLX/Python speech runtime with managed FFmpeg. Script Factory has a local unsigned bundle; signing, notarization and a public store release are not claimed.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "AI Engineering", "featured": true, "features": ["Local voice-reference and speech-generation workflows", "Script segmentation and selective regeneration", "Project and voice-profile persistence", "Managed model/runtime installation and repair", "Audio assembly and WAV/MP3 export"], "description": "Two related macOS desktop applications for local speech generation, voice-reference workflows and segmented audio production.", "technologies": ["Tauri", "React", "TypeScript", "Rust", "Python", "MLX", "Qwen3-TTS", "FFmpeg"], "project_status": "Local macOS applications · distribution in development", "evidence_attested": true, "challenges": ["Managing model/runtime installation and resumable generation without an external text-to-speech service."], "platforms": ["macOS / Apple Silicon"], "media_ids": []}'::jsonb,'{"body": "Script Factory and Content Factory turn written scripts into spoken audio using locally managed models and user-provided voice references. Their workflows cover project/script editing, voice profiles, segmented generation, selective regeneration, playback and final audio assembly.\n\nThese related applications are grouped as an engineering collection, rather than treated as a single renamed product. The documented stack combines Tauri, React, Rust and a local MLX/Python speech runtime with managed FFmpeg. Script Factory has a local unsigned bundle; signing, notarization and a public store release are not claimed.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "AI Engineering", "featured": true, "features": ["Local voice-reference and speech-generation workflows", "Script segmentation and selective regeneration", "Project and voice-profile persistence", "Managed model/runtime installation and repair", "Audio assembly and WAV/MP3 export"], "description": "Two related macOS desktop applications for local speech generation, voice-reference workflows and segmented audio production.", "technologies": ["Tauri", "React", "TypeScript", "Rust", "Python", "MLX", "Qwen3-TTS", "FFmpeg"], "project_status": "Local macOS applications · distribution in development", "evidence_attested": true, "challenges": ["Managing model/runtime installation and resumable generation without an external text-to-speech service."], "platforms": ["macOS / Apple Silicon"], "media_ids": []}'::jsonb,'{"title": "Local AI Audio Tools — Script & Content Factory | Anil Bishnoi", "description": "Two related macOS desktop applications for local speech generation, voice-reference workflows and segmented audio production.", "canonical": "https://anibish.com/portfolio/local-ai-audio-tools"}'::jsonb,'{"title": "Local AI Audio Tools — Script & Content Factory | Anil Bishnoi", "description": "Two related macOS desktop applications for local speech generation, voice-reference workflows and segmented audio production.", "canonical": "https://anibish.com/portfolio/local-ai-audio-tools"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/origin-dating','Origin Dating — Mobile Application MVP','portfolio','published','{"body": "Origin Dating is a mobile-first application for adults, with profile discovery, self-declared preferences, reciprocal matching and conversations. The documented MVP includes an authenticated API, an Expo/React Native client foundation and moderation-related backend work.\n\nThis is an active MVP record. A production-ready consumer launch, public app-store availability and every mobile journey are not claimed by this portfolio entry.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "Mobile Applications", "featured": false, "features": ["Authenticated profile and discovery foundations", "Swipe, like and mutual-match flows", "Messaging implementation", "Blocking, reporting and moderation foundations", "Shared iOS/Android client codebase"], "description": "An adults-only mobile dating application MVP with discovery, mutual matching, messaging and moderation foundations.", "technologies": ["React Native", "Expo", "TypeScript", "Fastify", "PostgreSQL", "Socket.IO"], "project_status": "Active MVP · production launch not verified", "evidence_attested": true, "challenges": [], "platforms": ["iOS/Android MVP"], "media_ids": []}'::jsonb,'{"body": "Origin Dating is a mobile-first application for adults, with profile discovery, self-declared preferences, reciprocal matching and conversations. The documented MVP includes an authenticated API, an Expo/React Native client foundation and moderation-related backend work.\n\nThis is an active MVP record. A production-ready consumer launch, public app-store availability and every mobile journey are not claimed by this portfolio entry.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "Mobile Applications", "featured": false, "features": ["Authenticated profile and discovery foundations", "Swipe, like and mutual-match flows", "Messaging implementation", "Blocking, reporting and moderation foundations", "Shared iOS/Android client codebase"], "description": "An adults-only mobile dating application MVP with discovery, mutual matching, messaging and moderation foundations.", "technologies": ["React Native", "Expo", "TypeScript", "Fastify", "PostgreSQL", "Socket.IO"], "project_status": "Active MVP · production launch not verified", "evidence_attested": true, "challenges": [], "platforms": ["iOS/Android MVP"], "media_ids": []}'::jsonb,'{"title": "Origin Dating — Mobile Application MVP | Anil Bishnoi", "description": "An adults-only mobile dating application MVP with discovery, mutual matching, messaging and moderation foundations.", "canonical": "https://anibish.com/portfolio/origin-dating"}'::jsonb,'{"title": "Origin Dating — Mobile Application MVP | Anil Bishnoi", "description": "An adults-only mobile dating application MVP with discovery, mutual matching, messaging and moderation foundations.", "canonical": "https://anibish.com/portfolio/origin-dating"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/social6','Social6 — Social Application Foundation','portfolio','published','{"body": "Social6 is an exploratory social-web project. The inspected source contains a React/Vite application shell, route/page foundations, a Fastify server and a PostgreSQL/Prisma project setup.\n\nThe available product README describes a broader social-media direction, while the inspected homepage is still a minimal shell. This entry therefore represents foundation and prototyping work; a functional social feed, chat service, finished authentication journey or launched community is not claimed.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "Web & SaaS Applications", "featured": false, "features": ["React application and routing foundations", "Typed backend server foundation", "Relational persistence project configuration", "Shared tooling and application structure"], "description": "An early full-stack social application foundation with a React frontend, typed backend and relational persistence configuration.", "technologies": ["React", "TypeScript", "Vite", "Fastify", "PostgreSQL", "Prisma"], "project_status": "Prototype foundation · business features incomplete", "evidence_attested": true, "challenges": [], "platforms": ["Web prototype"], "media_ids": []}'::jsonb,'{"body": "Social6 is an exploratory social-web project. The inspected source contains a React/Vite application shell, route/page foundations, a Fastify server and a PostgreSQL/Prisma project setup.\n\nThe available product README describes a broader social-media direction, while the inspected homepage is still a minimal shell. This entry therefore represents foundation and prototyping work; a functional social feed, chat service, finished authentication journey or launched community is not claimed.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [], "category": "Web & SaaS Applications", "featured": false, "features": ["React application and routing foundations", "Typed backend server foundation", "Relational persistence project configuration", "Shared tooling and application structure"], "description": "An early full-stack social application foundation with a React frontend, typed backend and relational persistence configuration.", "technologies": ["React", "TypeScript", "Vite", "Fastify", "PostgreSQL", "Prisma"], "project_status": "Prototype foundation · business features incomplete", "evidence_attested": true, "challenges": [], "platforms": ["Web prototype"], "media_ids": []}'::jsonb,'{"title": "Social6 — Social Application Foundation | Anil Bishnoi", "description": "An early full-stack social application foundation with a React frontend, typed backend and relational persistence configuration.", "canonical": "https://anibish.com/portfolio/social6"}'::jsonb,'{"title": "Social6 — Social Application Foundation | Anil Bishnoi", "description": "An early full-stack social application foundation with a React frontend, typed backend and relational persistence configuration.", "canonical": "https://anibish.com/portfolio/social6"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
